(function(){'use strict';
/* Animations Database generator — jahdb-animations-generator-1.0.
   Property of Justin Addam Higgins (JAH).
   Deterministic: same seed always makes the same record.
   src:"public" = Fact-checked public information */
function pad(n){var s=String(n);while(s.length<6)s='0'+s;return s;}
var PREFIX='JAH-ANIM-';
var SRC='public';
var RECORD_KIND='animation record';
var ANGLES=['overview','detailed','examples','faq','history','applications'];
var TOPICS=[{"brief":"Animation is the art of creating the illusion of motion by displaying a rapid sequence of still images, or frames, each differing slightly from the last.","examples":["A bouncing ball exercise teaches timing and spacing fundamentals.","A walk cycle demonstrates repeating-frame character motion."],"history":["Eadweard Muybridge's 1878 horse photographs proved sequential images read as motion.","The 1906 short Humorous Phases of Funny Faces is among the first true animated films."],"points":["The standard frame rates are 24 frames per second for film, 30 or 60 for video and games.","Each frame is a complete image; motion is perceived, not physically present.","Animation divides into 2D, 3D, stop motion, and motion graphics families.","A shot is built from key poses, in-betweens, timing, and spacing.","Digital tools replaced cels and film, but the principles are unchanged."],"qa":[["What is a frame?","One still image in the sequence; 24 of them make one second of film."],["Is animation only cartoons?","No — it spans CGI blockbusters, UI motion, data visualization, and simulations."],["What do animators actually draw or set?","Key poses and timing; software or assistants fill the in-betweens."]],"title":"Animation Fundamentals","uses":["Film and television entertainment.","Video games and interactive media.","Education, advertising, and scientific visualization."]},{"brief":"Motion perception in animation rests on how the visual system stitches discrete images into continuous movement — historically called persistence of vision, now better explained by the phi phenomenon and beta movement.","examples":["Theater marquee bulbs chasing each other demonstrate the phi phenomenon.","A flipbook at 12 fps looks choppy; at 24 fps it looks smooth."],"history":["Peter Mark Roget described persistence of vision in 1824.","Max Wertheimer's 1912 phi-phenomenon experiments founded Gestalt psychology."],"points":["The phi phenomenon: two flashing lights seen as one moving light.","Beta movement: optimal apparent motion between alternating images.","Critical flicker fusion: above ~50-60 Hz, flicker disappears.","Persistence of vision is an oversimplified myth; motion detectors in the brain do the real work.","Frame rate choice exploits these thresholds: 24 fps reads as smooth motion with motion blur."],"qa":[["Is persistence of vision real?","Only loosely — modern science credits neural motion processing, not retinal afterimages."],["Why 24 fps?","A compromise between film cost and smooth apparent motion with blur."],["What causes the wagon-wheel effect?","Temporal aliasing: the frame rate undersamples the rotation."]],"title":"Persistence of Vision and the Phi Phenomenon","uses":["Setting frame rates for film, games, and displays.","Designing LED signage and chase lighting.","Understanding motion sickness in VR."]},{"brief":"Keyframe animation defines important poses at specific times — the keys — and fills the frames between them, whether by an assistant animator or by software interpolation.","examples":["An animator keys a character's hand at a doorknob, then at the door fully open.","A bouncing ball is keyed at each contact and apex point."],"history":["Disney's 1930s animators formalized key and in-between roles.","Early 3D packages like PowerAnimator (1988) brought keyframing to CGI."],"points":["Keys carry the storytelling: contact poses, extremes, breakdowns.","Breakdowns refine the motion between keys.","Digital keyframing stores transform values per key on a timeline.","The graph editor exposes interpolation curves between keys.","Blocking first (rough keys), then splining and polish is the standard workflow."],"qa":[["What is a breakdown?","An in-between pose that defines the path of motion between two keys."],["Keys vs in-betweens?","Keys define the action; in-betweens just connect them smoothly."],["What is blocking?","Rough key poses staged for timing approval before refinement."]],"title":"Keyframe Animation","uses":["Character animation in film and games.","Motion graphics and UI animation.","Camera moves and object animation."]},{"brief":"Tweening (in-betweening) generates the frames between keyframes by interpolating values — linearly, or with easing curves that shape acceleration and deceleration.","examples":["A CSS transition with ease-in-out mimics natural acceleration.","Flash-era web cartoons used shape tweens for morphing effects."],"history":["Hand in-betweening was the entry-level Disney animator job.","Macromedia Flash (1996) popularized the term 'tween' for digital artists."],"points":["Linear interpolation moves at constant speed and usually looks robotic.","Ease-in starts slow and accelerates; ease-out decelerates into the pose.","Bezier and spline curves give animators precise control of interpolation.","Shape tweening morphs vector outlines between keys.","Good spacing — not just timing — sells weight and energy."],"qa":[["What is easing?","A curve shaping how interpolation accelerates — the basis of natural motion."],["Linear vs spline?","Linear is constant speed; splines ease through keys smoothly."],["Why does linear motion look wrong?","Real objects accelerate and decelerate; constant speed reads as mechanical."]],"title":"Tweening and Interpolation","uses":["Web and UI animation.","2D digital cartoons.","Motion graphics transitions."]},{"brief":"Cel animation paints characters on transparent celluloid sheets photographed over static painted backgrounds — the dominant commercial technique of the 20th century.","examples":["Snow White and the Seven Dwarfs (1937) used roughly 250,000 drawings.","The Rescuers Down Under (1990) was Disney's first fully CAPS feature."],"history":["Earl Hurd patented the cel process in 1914.","Disney's CAPS system ended the physical cel era around 1990."],"points":["Cels are transparent so only the character needs redrawing each frame.","Ink and paint departments traced and colored every cel by hand.","A 90-minute feature could require over 100,000 individual cels.","Xerography (101 Dalmatians, 1961) let pencil lines transfer directly to cels.","CAPS (1990) replaced physical cels with digital ink, paint, and compositing."],"qa":[["What is a cel?","A transparent celluloid sheet holding one frame's character art."],["Why transparent?","So backgrounds are painted once and reused under moving characters."],["When did cels end?","Digital ink-and-paint (CAPS) replaced them by the early 1990s."]],"title":"Cel Animation","uses":["Classic feature and television animation.","Collectible original production cels.","Study of traditional craft techniques."]},{"brief":"Stop motion animates physical objects — puppets, models, or everyday items — moved in tiny increments and photographed frame by frame.","examples":["King Kong (1933) pioneered stop-motion creature effects.","Coraline (2009) used 3D-printed replacement faces for lip sync."],"history":["J. Stuart Blackton's The Haunted Hotel (1907) showed early stop-motion tricks.","Willis O'Brien's King Kong (1933) made it a prestige effects technique."],"points":["24 individually posed photographs make one second of footage.","Puppets use ball-and-socket armatures for repeatable posing.","Clay, silicone, and 3D-printed replacement faces are common materials.","Go-motion adds motion blur by moving the puppet during exposure.","Digital capture software gives animators onion-skin previews."],"qa":[["How many photos per second?","Usually 24, sometimes shot on twos (12 unique poses)."],["What is an armature?","A posable metal skeleton inside the puppet."],["What is shooting on twos?","Holding each pose for two frames to halve the workload."]],"title":"Stop Motion","uses":["Feature films like Wallace & Gromit and Kubo.","Commercials and music videos.","Independent and student filmmaking."]},{"brief":"Claymation is stop motion with malleable clay figures, allowing squash, stretch, and morphing impossible with rigid puppets.","examples":["Wallace & Gromit shorts showcase classic clay character acting.","The California Raisins commercials made claymation a pop-culture staple."],"history":["Art Clokey's Gumby (1955) brought claymation to television.","Will Vinton trademarked the term 'Claymation' in the 1970s."],"points":["Oil-based clay (Plasticine) stays workable under hot lights.","Armatures inside clay figures hold poses between frames.","Clay allows direct morphing: a face can melt into another shape.","Fingerprints and surface wobble are the medium's signature texture.","Replacement animation swaps pre-sculpted parts for lip sync and expressions."],"qa":[["Why oil-based clay?","It never hardens, so figures stay posable for weeks of shooting."],["What causes the boiling texture?","Tiny unintentional surface shifts between frames — part of the charm."],["Clay vs puppet stop motion?","Clay morphs freely; rigid puppets hold detail but can't melt."]],"title":"Claymation","uses":["Character-driven short films.","Advertising mascots.","Children's television."]},{"brief":"Cutout animation moves flat paper or card pieces frame by frame under the camera — one of the oldest and cheapest animation methods.","examples":["South Park began as paper cutout; the show kept the look digitally.","Terry Gilliam's Monty Python animations used Victorian engraving cutouts."],"history":["Lotte Reiniger's silhouette films (1920s) elevated cutout to art.","Noble Studios' digital cutout powered 2000s television production."],"points":["Characters are jointed flat puppets with movable limbs.","Pieces are repositioned slightly between exposures.","Digital cutout rigs in software mimic the paper-puppet workflow.","The style's flatness became an aesthetic choice, not just a budget limit.","Replacement mouths and eyes handle dialogue and expression."],"qa":[["Is South Park still cutout?","Digital now, but deliberately preserving the paper-cutout look."],["Silhouette animation?","Lotte Reiniger's backlit black-paper technique — cutout's elegant cousin."],["Advantage over cel?","Far fewer drawings: the same pieces are reused every frame."]],"title":"Cutout Animation","uses":["Television comedy series.","Educational and explainer videos.","Independent shorts."]},{"brief":"The flipbook — a stack of pages with incremental drawings, thumbed rapidly — is the simplest true animation device and the animator's pocket sketchbook.","examples":["Classroom flipbooks teach timing with a bouncing ball.","Animators flip paper scenes to check arcs and spacing."],"history":["Linnett's 1868 kineograph patent is the first flipbook.","Flipbooks were Victorian parlor novelties before cinema."],"points":["Each page holds one frame; thumbing flips them at speed.","The kineograph was patented by John Barnes Linnett in 1868.","Animators still flip paper drawings to test motion before committing.","Digital onion-skinning replicates the flipbook test on screen.","A good flipbook runs 24+ pages for a second of motion."],"qa":[["Who invented the flipbook?","John Barnes Linnett patented the kineograph in 1868."],["Why do animators still use them?","Instant motion test with zero setup — feel the timing in your hands."],["How many pages for one second?","About 24 for film timing, fewer if held on twos."]],"title":"Flipbooks","uses":["Animation education and testing.","Novelty books and marketing.","Prototyping motion ideas."]},{"brief":"Before film, optical toys like the phenakistoscope, zoetrope, and praxinoscope turned spinning drawings into moving pictures — animation's direct ancestors.","examples":["Museum zoetropes still delight with galloping-horse strips.","Studio Ghibli's famous 3D zoetrope uses strobe-lit Totoro figures."],"history":["Simon Stampfer and Joseph Plateau independently invented the phenakistoscope in 1832.","Émile Reynaud's praxinoscope led to his 1892 Théâtre Optique screenings."],"points":["Phenakistoscope (1832): spinning disc viewed in a mirror.","Zoetrope (1834): slitted drum; viewers watch through the slots.","Praxinoscope (1877): mirrored drum, brighter and clearer.","All exploit the phi phenomenon with discrete sequential images.","Muybridge's zoopraxiscope (1879) projected photographic motion."],"qa":[["Zoetrope vs praxinoscope?","Zoetrope uses slits; praxinoscope uses mirrors — brighter image."],["First projected animation?","Reynaud's Théâtre Optique, Paris, 1892."],["Why do they matter?","They proved sequential drawings read as motion — animation's founding insight."]],"title":"Zoetrope and Pre-Cinema Devices","uses":["Museum and science-center exhibits.","Teaching apparent motion.","Art installations."]},{"brief":"The multiplane camera stacks glass-painted layers at different depths and moves the camera through them, creating true parallax in 2D animation.","examples":["Snow White's forest flight uses multiplane depth.","Pinocchio's opening village pan is a multiplane signature shot."],"history":["Ub Iwerks built a multiplane in the early 1930s.","Disney's definitive camera debuted with The Old Mill (1937)."],"points":["Foreground, midground, and background move at different speeds — parallax.","Disney's 1937 multiplane stood 12 feet tall.","The Old Mill (1937) was its showcase short.","Ub Iwerks built an earlier version before leaving Disney.","Digital parallax in compositing software replicates it cheaply."],"qa":[["What is parallax?","Near layers move faster than far ones — the cue for depth."],["Who invented it?","Ub Iwerks built the first; Disney perfected the famous version."],["Digital equivalent?","Layered planes in After Effects or any compositor."]],"title":"The Multiplane Camera","uses":["Classic feature depth effects.","Digital parallax in motion graphics.","Side-scrolling game backgrounds."]},{"brief":"Rotoscoping traces live-action footage frame by frame to produce realistic animated motion — patented by Max Fleischer in 1915 and still used in effects work.","examples":["Snow White's dancing was rotoscoped from live performers.","Waking Life (2001) rotoscoped digital video into painted dreamscapes."],"history":["Max Fleischer patented rotoscoping in 1915.","The Fleischer studio used it for Koko the Clown and Gulliver's Travels."],"points":["Fleischer's 1915 patent covered projecting film onto a drawing board.","It captures human movement nuance impossible to invent cold.","Critics called it cheating; animators call it reference.","Digital rotoscoping now means masking and isolating elements in footage.","A-ha's 'Take On Me' (1985) made rotoscope a music-video icon."],"qa":[["Who invented rotoscoping?","Max Fleischer, patented 1915."],["Is it cheating?","Animators treat it as reference; the acting choices remain theirs."],["Modern meaning?","Also the VFX craft of cutting mattes around live elements."]],"title":"Rotoscoping","uses":["Realistic character motion reference.","Visual effects masking and cleanup.","Stylized rotoscope films."]},{"brief":"2D vector animation builds characters from mathematical curves rather than pixels, enabling smooth scaling, small files, and procedural tweening.","examples":["Foster's Home and My Little Pony used Flash-style vector pipelines.","Lottie animations deliver vector motion in mobile apps."],"history":["FutureSplash Animator (1996) became Macromedia Flash.","Adobe Animate is Flash's modern successor."],"points":["Vectors are resolution-independent: one asset works at any size.","Shape tweening morphs one outline into another.","Bone tools add skeletal rigs to flat artwork.","File sizes stay tiny compared to frame-by-frame bitmap.","The Flash-era web ran on vector animation's efficiency."],"qa":[["Vector vs bitmap?","Vectors are math curves (infinitely scalable); bitmaps are pixel grids."],["What killed Flash?","Mobile, HTML5, and security issues — but vector animation lives on."],["What is Lottie?","A JSON-based vector animation format for apps and web."]],"title":"2D Vector Animation","uses":["Web cartoons and explainer videos.","Mobile app UI animation via Lottie.","Broadcast motion graphics."]},{"brief":"Sprite animation builds game characters from small bitmap images — sprites — swapped or shifted across frames, the foundation of 2D game motion.","examples":["Mario's run cycle is a handful of 16x16 pixel sprites.","Fighting games store hundreds of hand-drawn sprite frames per character."],"history":["1970s arcade hardware made hardware sprites standard.","Sprite sheets and texture atlases organized frames for 1990s games."],"points":["A sprite is a small bitmap drawn over the background each frame.","Sprite sheets pack all frames of an animation into one image.","Palette swapping recolors the same sprite for variants.","Parallax layers of sprites fake depth in side-scrollers.","Pixel art constraints (16x16, 32x32) shaped a whole aesthetic."],"qa":[["What is a sprite sheet?","One image containing every frame of a character's animations."],["Why pixel art?","Hardware limits made tiny sprites necessary; the style outlived the limits."],["Sprites vs 3D?","Sprites are flat images; 3D uses geometry — sprites are cheaper to draw."]],"title":"Sprite Animation","uses":["2D platformers and retro games.","Mobile game UI and effects.","Pixel-art indie titles."]},{"brief":"Motion graphics animates graphic design — typography, shapes, and logos in motion — for titles, broadcast packages, and explainer videos.","examples":["Saul Bass's Vertigo (1958) titles made motion graphics cinematic.","News channel packages animate logos, lower thirds, and transitions."],"history":["Saul Bass and John Whitney pioneered it in 1950s title design.","After Effects (1993) democratized broadcast-quality motion graphics."],"points":["Combines graphic design principles with animation timing.","Kinetic typography is its most recognizable form.","Easing and anticipation apply just as in character animation.","Used for title sequences, ads, explainers, and data visualization.","Software: After Effects, Cavalry, and node-based compositors."],"qa":[["Motion graphics vs animation?","Motion graphics animates design elements; character animation acts."],["Who is Saul Bass?","The title designer who made opening credits an art form."],["Tools of the trade?","After Effects dominates; Cavalry and Rive are rising."]],"title":"Motion Graphics","uses":["Film and TV title sequences.","Advertising and brand idents.","Explainer and data videos."]},{"brief":"Kinetic typography sets text itself in motion — letters that fly, scale, and dance in sync with voiceover or music.","examples":["Lyric videos animate every sung word.","Apple keynote slides use kinetic type for emphasis."],"history":["Saul Bass's title sequences hinted at it in the 1960s.","Digital tools made per-letter animation trivial in the 2000s."],"points":["Text becomes the actor: emphasis through motion, not just layout.","Sync to audio is critical — words land on beats.","Per-character animators in After Effects drive most kinetic type.","Legibility constrains the choreography.","Used in lyric videos, ads, and title design."],"qa":[["Why animate text?","Motion directs the eye and adds emotional emphasis."],["Key tool?","After Effects' per-character text animators."],["Risk?","Over-animation destroys readability — restraint matters."]],"title":"Kinetic Typography","uses":["Lyric and music videos.","Advertising and title design.","Presentation graphics."]},{"brief":"3D computer animation models characters and worlds as geometry in virtual space, then moves, lights, and renders them — the pipeline behind modern features and games.","examples":["Toy Story (1995) was the first fully CGI feature.","Modern games render 3D characters at 60 fps in real time."],"history":["Ed Catmull's 1972 hand animation was an early 3D milestone.","Toy Story (1995) proved features could be fully computer-animated."],"points":["The pipeline: modeling, rigging, animation, lighting, rendering, compositing.","Geometry is polygons, NURBS, or subdivision surfaces.","Cameras are virtual: focal length, depth of field, and motion are simulated.","Offline renderers take hours per frame; game engines render in milliseconds.","The 12 principles apply in 3D exactly as in 2D."],"qa":[["Why does CGI take so long?","Path-traced frames can take hours each on render farms."],["Real-time vs offline?","Games render instantly at lower fidelity; films render slowly at maximum quality."],["First CGI feature?","Toy Story (1995)."]],"title":"3D Computer Animation","uses":["Animated features and VFX.","Video games.","Architectural and product visualization."]},{"brief":"Polygonal modeling builds 3D surfaces from vertices, edges, and faces — box modeling, extrusion, and sculpting turn primitives into characters and worlds.","examples":["A character head starts as a subdivided cube.","Sculpting tools carve pores and wrinkles like digital clay."],"history":["Early CGI used wireframes and flat-shaded polygons.","Subdivision surfaces (Geri's Game, 1997) made smooth organic models practical."],"points":["Vertices, edges, and faces are the atomic units.","Box modeling extrudes detail from simple primitives.","Sculpting displaces millions of polygons like clay.","Topology — clean edge flow — determines how models deform.","Retopology rebuilds sculpted meshes into animation-friendly geometry."],"qa":[["What is topology?","The arrangement of polygons — clean flow deforms cleanly."],["Quads vs triangles?","Quads subdivide and deform predictably; games triangulate at render."],["What is retopology?","Rebuilding a dense sculpt as a clean low-poly animation mesh."]],"title":"Polygonal Modeling","uses":["Character and prop creation.","Game asset pipelines.","3D printing preparation."]},{"brief":"Rigging builds the skeletal control system inside a 3D model — joints, controllers, and constraints that let animators pose it like a digital puppet.","examples":["A character rig has hand, foot, spine, and face controllers.","Facial rigs use dozens of controls for lip sync and expression."],"history":["Hierarchical skeletons came from early 3D research in the 1980s.","Feature rigs grew from tens to hundreds of controls by the 2000s."],"points":["Joints form a hierarchy: moving a shoulder moves the arm.","Controllers are animator-friendly handles hiding joint complexity.","Constraints link objects: aim, parent, and point constraints.","Facial rigging uses bones, blendshapes, or both.","A good rig is invisible — animators think in poses, not joints."],"qa":[["Rigger vs animator?","Riggers build the puppet; animators perform with it."],["What is a blendshape?","A stored facial pose blended in for expressions."],["Why constraints?","To automate relationships like eyes tracking a target."]],"title":"Rigging and Skeletons","uses":["Feature and game character setup.","Creature and prop rigging.","Facial performance systems."]},{"brief":"Skinning binds a 3D mesh to its skeleton so vertices follow joints; weight painting controls how much influence each joint has on each vertex.","examples":["A shoulder bends smoothly when weights blend across the joint.","A candy-wrapper elbow shows bad weights pinching at the bend."],"history":["Smooth skinning replaced rigid binding in 1990s 3D packages.","Dual-quaternion skinning (2000s) fixed volume loss in twists."],"points":["Each vertex gets weights summing to 1.0 across influencing joints.","Weight painting is done with brush tools on the 3D model.","Rigid skinning assigns each vertex to exactly one joint.","Smooth skinning blends joints for organic deformation.","Dual-quaternion and corrective blendshapes fix collapse at elbows and shoulders."],"qa":[["What is a weight?","How much a joint pulls a vertex — painted like a heat map."],["Candy-wrapper effect?","Twisting collapse from linear blend skinning; dual-quaternion fixes it."],["Who paints weights?","Usually the rigger or character TD, refined with the animator."]],"title":"Skinning and Weight Painting","uses":["Character deformation setup.","Creature muscle systems.","Game character pipelines."]},{"brief":"Inverse kinematics poses a joint chain by moving its end effector — the hand or foot — while the solver computes the joint angles, complementing forward kinematics.","examples":["Planting a foot on the ground uses IK so it stays put.","Reaching for a doorknob is posed with an IK hand target."],"history":["Robotics developed IK solvers decades before animation adopted them.","Two-bone analytic IK became standard in 1990s 3D software."],"points":["FK rotates each joint directly; IK solves from the end backward.","IK keeps feet planted and hands on targets.","Pole vectors aim knees and elbows.","Animators switch between IK and FK per shot need.","Full-body IK solvers pose entire characters from a few handles."],"qa":[["IK vs FK?","FK: rotate joints directly. IK: drag the hand, joints follow."],["What is a pole vector?","A control aiming the knee/elbow direction in an IK chain."],["When to use FK?","Arcing swings like a waving arm read better in FK."]],"title":"Inverse Kinematics","uses":["Walk cycles and foot planting.","Hand-target interactions.","Real-time game posing."]},{"brief":"Motion capture records real performers' movement with cameras, suits, or inertial sensors, then retargets it onto digital characters.","examples":["Gollum's movement came from Andy Serkis in a mocap suit.","Sports games capture real athletes for authentic motion."],"history":["Optical mocap matured in the 1990s for games and film.","The Lord of the Rings (2001-2003) proved mocap creatures could act."],"points":["Optical systems track reflective markers with multiple cameras.","Inertial suits use accelerometers and gyroscopes, no cameras needed.","Data is cleaned, then retargeted onto the character rig.","Mocap captures nuance; animators still edit and enhance it.","Markerless systems now track from ordinary video."],"qa":[["Does mocap replace animators?","No — cleanup, retargeting, and enhancement are animation work."],["Optical vs inertial?","Optical is precise but needs a stage; inertial works anywhere."],["What is retargeting?","Mapping captured motion onto a different-proportioned character."]],"title":"Motion Capture","uses":["Film creature and character performance.","Sports and action video games.","Virtual production and VTubing."]},{"brief":"Performance capture records face, body, voice, and fingers simultaneously — the full acting instrument — for digital characters.","examples":["Avatar (2009) captured actors' faces with head-mounted cameras.","Planet of the Apes' Caesar combined body and facial capture on set."],"history":["The Polar Express (2004) attempted early full performance capture.","Avatar (2009) made it the prestige standard."],"points":["Head rigs with tiny cameras record facial markers or video.","Body, face, and voice are captured in the same take.","Facial solving converts markers to rig or blendshape animation.","On-set capture lets actors perform together in costume.","Animators refine the solve: capture is the start, not the finish."],"qa":[["Mocap vs performance capture?","Performance capture adds the face and records everything together."],["Head-mounted cameras?","Tiny cameras filming the actor's face during the take."],["Still needs animators?","Yes — solving, cleanup, and artistic enhancement."]],"title":"Performance Capture","uses":["Feature creature performances.","AAA game cinematics.","Virtual production."]},{"brief":"Procedural animation generates motion with code and rules at runtime instead of authored keyframes — ragdolls, walk cycles, and secondary motion computed live.","examples":["Ragdoll deaths in games are simulated, never keyframed.","A character's coat sways via procedural secondary motion."],"history":["Craig Reynolds' boids (1986) showed lifelike group motion from rules.","Games adopted ragdoll physics in the early 2000s."],"points":["Motion is computed from inputs: speed, terrain, and physics.","Ragdolls simulate jointed bodies with rigid-body dynamics.","Locomotion systems blend and steer walk cycles procedurally.","Procedural layering adds breathing, sway, and look-at on top of authored animation.","It's reactive: the same code produces different motion every run."],"qa":[["Procedural vs keyframed?","Keyframed is authored; procedural is computed live from rules."],["What is a ragdoll?","A simulated jointed body that collapses realistically."],["Boids?","Reynolds' 1986 flocking rules: separation, alignment, cohesion."]],"title":"Procedural Animation","uses":["Game physics and ragdolls.","Crowd and flocking systems.","Runtime secondary motion."]},{"brief":"Particle systems simulate thousands of tiny elements — sparks, smoke, rain, magic — with simple per-particle rules producing complex collective behavior.","examples":["Star Trek II's Genesis effect used pioneering particle fire.","Game spell effects are textured particles with physics."],"history":["Bill Reeves' 1983 particle paper founded the technique.","Pixar and ILM industrialized particles for effects work."],"points":["Each particle has position, velocity, life, size, and color.","Emitters spawn particles with randomized initial conditions.","Forces: gravity, wind, turbulence, and attraction.","Rendering as points, sprites, or instanced geometry.","GPU particles simulate millions in real time."],"qa":[["Who invented particle systems?","Bill Reeves at Lucasfilm, 1983."],["Points vs sprites?","Points are pixels; sprites are textured quads facing the camera."],["Why randomize?","Variation hides repetition — no two sparks alike."]],"title":"Particle Systems","uses":["Fire, smoke, and explosion effects.","Magic and energy effects in games.","Rain, snow, and dust."]},{"brief":"Cloth simulation drapes virtual fabric by modeling it as a grid of particles connected by springs, solved with constraints each frame.","examples":["A character's cape flows with verlet-integrated cloth.","Tablecloths in product renders use true fabric simulation."],"history":["1990s research papers made cloth practical.","Feature films adopted it for costumes in the 2000s."],"points":["Cloth is a particle grid with stretch, shear, and bend constraints.","Verlet integration is stable and fast for cloth.","Collision with the character body keeps cloth outside the skin.","Wind and turbulence add life; damping prevents jitter.","Hero cloth gets high resolution; background cloth stays coarse."],"qa":[["How is cloth modeled?","A grid of particles linked by spring constraints."],["Why does cloth jitter?","Too-stiff constraints or large timesteps cause instability."],["Real-time cloth?","Games use low-res cloth with simplified collision."]],"title":"Cloth Simulation","uses":["Character costumes and capes.","Flags and banners.","Product and fashion visualization."]},{"brief":"Hair and fur simulation grows thousands of guide strands from a groomed surface, then simulates and renders them as curves with shading and collision.","examples":["Monsters, Inc.'s Sulley had over 2 million simulated hairs.","Digital doubles need scalp, brow, and stubble grooms."],"history":["Early 2000s features made fur a competitive showcase.","Monsters, Inc. (2001) set the fur-simulation benchmark."],"points":["Artists groom guide hairs; software interpolates the full coat.","Strands are simulated as chained particles with constraints.","Collision keeps hair out of the body and clothes.","Shading uses anisotropic highlights along each strand.","Clumping, frizz, and wind sell realism."],"qa":[["How many hairs?","Hero creatures carry millions of rendered strands."],["Guide hairs?","A few thousand artist-placed strands interpolated to millions."],["Hardest part?","Collision and art-directable clumping."]],"title":"Hair and Fur Simulation","uses":["Creature features.","Digital humans.","Pet and animal advertising."]},{"brief":"Fluid simulation solves simplified Navier-Stokes equations on grids or particles to animate water, smoke, and fire convincingly.","examples":["Ocean storms in features use FLIP water solvers.","Explosions combine fluid smoke with particle embers."],"history":["Stam's 1999 stable fluids paper made smoke practical.","FLIP (2007) brought detailed water to features."],"points":["Grid-based solvers handle smoke and fire well.","FLIP and SPH are particle methods for liquids.","Vorticity confinement preserves swirl detail.","Emission sources and colliders art-direct the flow.","Caches are stored so animation timing stays editable."],"qa":[["FLIP?","Fluid-Implicit-Particle: particles carry a grid's detail — great water."],["Why so slow?","High-resolution 3D grids need massive computation."],["Art-directable?","Emitters, forces, and masks steer the sim."]],"title":"Fluid Simulation","uses":["Water and ocean effects.","Smoke, fire, and explosions.","Product liquid pours."]},{"brief":"Rigid body dynamics simulates non-deforming objects colliding, tumbling, and stacking — destruction, debris, and physics puzzles.","examples":["A collapsing building in a film is rigid-body destruction.","Game crates tumble with real-time rigid bodies."],"history":["1990s research brought rigid bodies to film effects.","Game physics engines (Havok, PhysX) made them real-time."],"points":["Objects have mass, velocity, and angular momentum.","Collision detection finds contacts; solvers resolve them.","Fracture pre-breaks objects into simulatable chunks.","Sleeping lets settled objects skip computation.","Game engines run simplified solvers at 60 Hz."],"qa":[["What is fracture?","Pre-breaking geometry into pieces the solver can scatter."],["Sleeping?","Deactivating settled bodies to save computation."],["Film vs game?","Film uses high-accuracy offline; games use fast approximations."]],"title":"Rigid Body Dynamics","uses":["Destruction effects.","Game physics interactions.","Engineering visualization."]},{"brief":"Soft body dynamics simulates deformable objects — flesh, jelly, rubber — that squash, jiggle, and recover under forces.","examples":["Creature bellies jiggle with soft-body secondary motion.","A bouncing jelly dessert shows elastic deformation."],"history":["Soft bodies grew from cloth and finite-element research.","Games use simplified soft bodies for characters and props."],"points":["Volumes are modeled as particle lattices or tetrahedral meshes.","Elasticity, damping, and plasticity are tunable.","Pressure models inflate balloons and tires.","Flesh simulation adds jiggle over the skeleton.","Games fake it with jiggle bones and vertex shaders."],"qa":[["Soft vs rigid?","Soft bodies deform; rigid bodies only translate and rotate."],["Finite elements?","A continuum method dividing volumes into tiny elements."],["Game shortcut?","Jiggle bones and shader wobble instead of true simulation."]],"title":"Soft Body Dynamics","uses":["Creature flesh and fat.","Food and product deformation.","Game character secondary motion."]},{"brief":"Crowd simulation animates thousands of agents with individual behaviors — stadium crowds, armies, and city streets — from simple rules.","examples":["The Lord of the Rings' battles used Massive's autonomous agents.","Stadium crowds in sports games are instanced animated agents."],"history":["Weta's Massive software (1999) pioneered agent crowds.","Boids research (1986) provided the behavioral foundation."],"points":["Agents perceive neighbors and follow behavior rules.","Variety comes from randomized models, textures, and motion clips.","Level of detail swaps near heroes for full characters, far crowds for cards.","Collision avoidance keeps agents from interpenetrating.","Directors paint flow fields and goals to art-direct the mass."],"qa":[["What is Massive?","Weta's pioneering autonomous-agent crowd software."],["How to avoid identical clones?","Randomized assets, motion variation, and LOD."],["Flow fields?","Vector fields steering crowd direction like invisible currents."]],"title":"Crowd Simulation","uses":["Battle and stadium scenes.","City population in games.","Architectural crowd studies."]},{"brief":"Rendering converts 3D scenes into 2D images — rasterization for speed, ray tracing for realism — through cameras, lights, and materials.","examples":["A film frame may take hours on a render farm.","A game frame must render in 16 milliseconds."],"history":["The Utah teapot (1975) became rendering's test model.","Pixar's RenderMan standardized film rendering in the 1990s."],"points":["Rasterization projects triangles to pixels — fast, the game standard.","Ray tracing simulates light rays for reflections and shadows.","Shaders define how surfaces respond to light.","Render farms distribute frames across thousands of machines.","Denoising lets fewer rays produce clean images."],"qa":[["Rasterization vs ray tracing?","Rasterization is fast projection; ray tracing simulates light transport."],["What is a render farm?","A cluster splitting frames across many machines."],["Why denoising?","To clean noisy low-sample renders quickly."]],"title":"Rendering and Shading","uses":["Film final frames.","Game real-time graphics.","Product and architectural visualization."]},{"brief":"Ray tracing renders by tracing light paths — reflections, refractions, shadows, and global illumination — now accelerated by GPU hardware.","examples":["RTX GPUs brought real-time ray-traced reflections to games.","Feature films path-trace nearly every frame."],"history":["Turner Whitted's 1980 paper introduced recursive ray tracing.","NVIDIA RTX (2018) put ray tracing hardware in consumer GPUs."],"points":["Primary rays find visible surfaces; secondary rays add effects.","Path tracing follows many random bounces for full global illumination.","Hardware RT cores accelerate ray-triangle intersection.","Hybrid renderers mix rasterization with ray-traced effects.","Monte Carlo noise is cleaned with denoisers."],"qa":[["Who pioneered ray tracing?","Turner Whitted's 1980 recursive ray tracing paper."],["What are RT cores?","Fixed-function hardware accelerating ray intersection tests."],["Path tracing?","Tracing many random light paths per pixel for realism."]],"title":"Ray Tracing in Animation","uses":["Feature film rendering.","Real-time game lighting.","Product visualization."]},{"brief":"Global illumination simulates indirect light — bounce, color bleeding, and ambient occlusion — so rendered scenes feel lit by a real world, not a lamp.","examples":["A red wall tints nearby white surfaces pink.","Corners darken naturally with ambient occlusion."],"history":["Radiosity (1984) first simulated diffuse bounce.","Path tracing made full GI the film standard by the 2010s."],"points":["Direct light comes from lamps; GI adds all the bounces.","Color bleeding tints surfaces with neighbors' colors.","Ambient occlusion darkens crevices cheaply.","Irradiance caches and lightmaps store GI for reuse.","Real-time GI uses probes, screen-space tricks, or hardware rays."],"qa":[["Radiosity vs path tracing?","Radiosity solved diffuse bounce; path tracing handles everything stochastically."],["Ambient occlusion?","A cheap darkening in crevices approximating blocked indirect light."],["Real-time GI?","Probe volumes and screen-space methods approximate it."]],"title":"Global Illumination","uses":["Film-quality rendering.","Game lighting probes.","Architectural visualization."]},{"brief":"Squash and stretch — the first of Disney's 12 principles — deforms a character to show weight, flexibility, and force while preserving volume.","examples":["A bouncing ball squashes on impact and stretches in flight.","A character anticipates a jump by squashing down first."],"history":["Formalized by Disney animators in the 1930s.","Documented in The Illusion of Life (1981)."],"points":["Volume stays constant: squash wide, stretch tall.","Exaggerates flexibility and impact.","Rigid objects use subtler versions.","Applies in 3D via scale and deformers.","Overuse turns characters to jelly — restraint matters."],"qa":[["Why preserve volume?","Constant volume keeps the deformation believable."],["Applies to 3D?","Yes — scale and lattice deformers do the job."],["How much is too much?","When the character reads as liquid, pull back."]],"title":"Squash and Stretch","uses":["Character animation in all media.","Motion graphics emphasis.","Game juice and feedback."]},{"brief":"Anticipation prepares the audience for an action with a small opposite move — the wind-up before the pitch — making motion readable.","examples":["A character crouches before jumping.","A pitcher winds up before throwing."],"history":["Disney animators identified it as a core principle in the 1930s.","The Illusion of Life (1981) codified all twelve principles."],"points":["The anticipation moves opposite the main action.","Bigger actions need bigger anticipations.","It tells the audience where to look.","Without it, actions feel abrupt and confusing.","Comedy timing lives in the anticipation pause."],"qa":[["Example?","Crouch before a jump; look before a turn."],["Why opposite?","Contrast makes the main action pop."],["In UI?","A button presses in slightly before the panel springs out."]],"title":"Anticipation","uses":["Character acting.","Game attack telegraphs.","UI micro-interactions."]},{"brief":"Staging presents each idea clearly — camera, pose, and composition arranged so the audience instantly understands the story point.","examples":["A villain's entrance uses low angle and silhouette.","A clear silhouette pose reads instantly even in thumbnail."],"history":["Borrowed from theater and film directing.","A core Disney principle from the 1930s."],"points":["Every shot should communicate one clear idea.","Silhouette readability is the test.","Direct the eye with contrast, framing, and motion.","Avoid staging two important actions at once.","Applies to camera, lighting, and performance together."],"qa":[["The silhouette test?","If the pose reads as a black shape, the staging works."],["One idea per shot?","Clarity beats complexity — stage the story point."],["In UI animation?","One element moves at a time to guide attention."]],"title":"Staging","uses":["Shot composition.","Character posing.","Presentation design."]},{"brief":"Straight-ahead animation draws frame by frame from start to finish; pose-to-pose plans key poses first, then fills in — the two fundamental workflows.","examples":["Fire and water effects are often animated straight ahead.","A dialogue scene is blocked pose-to-pose for acting control."],"history":["Early animators worked purely straight ahead.","Disney's 1930s system formalized pose-to-pose planning."],"points":["Straight ahead: spontaneous, fluid, unpredictable — great for effects.","Pose to pose: planned keys, controlled timing — great for acting.","Digital tools favor pose-to-pose with interpolation.","Blocking, splining, and polish refine pose-to-pose.","Masters mix both: plan the acting, improvise the effects."],"qa":[["Which is better?","Neither — effects favor straight ahead, acting favors pose-to-pose."],["Digital equivalent?","Straight ahead is frame-by-frame; pose-to-pose is keyframing."],["Can they mix?","Yes — plan keys, then improvise overlapping details."]],"title":"Straight Ahead and Pose to Pose","uses":["Effects animation.","Character acting scenes.","Choosing a workflow per shot."]},{"brief":"Follow through lets parts continue past the main action's stop; overlapping action staggers parts so nothing starts and stops together — the physics of loose appendages.","examples":["A coat keeps swinging after the character halts.","Hair settles a beat after the head stops turning."],"history":["Disney animators observed real-world inertia in the 1930s.","The principle formalized drag and settle in character motion."],"points":["Loose parts lag behind, then overshoot and settle.","Stagger timing so elements don't move in lockstep.","Ears, tails, capes, and hair all follow through.","Adds weight and naturalism cheaply.","In 3D, dynamic simulations can drive it."],"qa":[["Follow through vs overlapping?","Follow through: parts continue after the stop. Overlapping: parts move at different times."],["Example?","A dog's ears flop after it stops running."],["Simulated?","Cloth and hair solvers automate it in 3D."]],"title":"Follow Through and Overlapping Action","uses":["Character secondary motion.","Creature animation.","Cloth and hair behavior."]},{"brief":"Slow in and slow out spaces more drawings near the extremes of a motion and fewer in the middle — natural acceleration rendered as spacing.","examples":["A pendulum clusters frames at each end of its swing.","A hand eases into a pointing pose."],"history":["Traditional animators charted spacing on exposure sheets.","Digital curves replicate it with bezier easing."],"points":["More in-betweens near keys, fewer mid-motion.","Reads as easing: acceleration and deceleration.","Linear spacing looks mechanical.","The graph editor's curves are the digital version.","Applies to everything from walks to camera moves."],"qa":[["Slow in vs slow out?","Slow in: ease into a pose. Slow out: ease out of it."],["Digital tool?","The animation curve editor's bezier handles."],["Why not linear?","Real motion accelerates; linear reads as robotic."]],"title":"Slow In and Slow Out","uses":["All keyframed animation.","UI easing curves.","Camera moves."]},{"brief":"Arcs — the seventh principle — observes that living things move along curved paths, not straight lines; arcing trajectories feel natural.","examples":["An arm swing traces an arc, never a straight line.","A thrown ball follows a parabolic arc."],"history":["Disney animators noted circular motion in the 1930s.","The Illusion of Life (1981) listed arcs among the twelve principles."],"points":["Limbs rotate around joints, producing arcs.","Straight-line motion reads as mechanical.","Breakdowns define the arc's curve.","In 3D, the graph editor reveals arc breaks.","Exceptions: deliberate mechanical or snappy motion."],"qa":[["Why arcs?","Joints rotate — rotation produces curves."],["How to check?","Trace the hand's path: it should curve."],["When to break arcs?","For robotic characters or snappy cartoon hits."]],"title":"Arcs","uses":["Character limb motion.","Camera path planning.","UI gesture animation."]},{"brief":"Secondary action supports the main action with smaller simultaneous motion — a character whistling while walking — enriching performance without stealing focus.","examples":["A character taps fingers while delivering bad news.","A walk gains life from swinging arms and bobbing head."],"history":["Identified by Disney animators in the 1930s.","The Illusion of Life (1981) codified it as a principle."],"points":["Secondary action supports; it never dominates.","It must not confuse the primary story point.","Adds personality and naturalism.","Examples: breathing, fidgeting, cloth sway.","Stage it clearly or cut it."],"qa":[["Secondary vs primary?","Primary tells the story; secondary flavors it."],["Danger?","A busy secondary action can steal focus."],["Example?","Whistling while walking."]],"title":"Secondary Action","uses":["Character performance.","Idle animations in games.","Enriching simple motions."]},{"brief":"Timing — the number of frames an action takes — defines weight, mood, and meaning: the same move reads differently at different speeds.","examples":["A 6-frame punch feels snappy; a 24-frame punch feels heavy.","Comedy lives in unexpected timing."],"history":["Exposure sheets let 1930s animators plan timing precisely.","Digital timelines made timing infinitely adjustable."],"points":["Fewer frames: fast, light, energetic.","More frames: slow, heavy, graceful.","Timing conveys mass: heavy things move slower.","Vary timing to avoid monotony.","Test timing with playblasts before polishing."],"qa":[["Timing vs spacing?","Timing: how many frames. Spacing: where things are each frame."],["Timing and weight?","Heavy objects need more frames to accelerate."],["Comedy timing?","Holds, then sudden moves — surprise through timing."]],"title":"Timing","uses":["All animation.","Comedy and drama pacing.","Game feel tuning."]},{"brief":"Exaggeration pushes reality beyond literal truth — bigger squash, wilder takes — for clarity and entertainment, while staying rooted in observation.","examples":["A double-take stretches the neck impossibly.","A shocked character's eyes pop twice their size."],"history":["Disney's 1930s style balanced realism with caricature.","The Illusion of Life (1981) framed exaggeration as stylized truth."],"points":["Exaggerate the essence, not random details.","Rooted in real observation, pushed further.","Too little reads flat; too much reads as chaos.","Varies by style: subtle in drama, wild in comedy.","Applies to poses, timing, and expressions alike."],"qa":[["Exaggeration vs distortion?","Exaggeration clarifies the idea; distortion just breaks it."],["How much?","Enough to read clearly at speed — then a touch more."],["In realistic styles?","Subtle: pushed timing and posed emphasis."]],"title":"Exaggeration","uses":["Cartoon performance.","Emphasizing story points.","Game hit reactions."]},{"brief":"Solid drawing grounds animation in draftsmanship — form, weight, and volume — while appeal makes characters charismatic and worth watching.","examples":["Milt Kahl's drawings show form in every pose.","Appeal is why audiences love a simple flour sack test."],"history":["Disney's 1930s training program drilled solid drawing.","Appeal became a hiring criterion at the studio."],"points":["Solid drawing: anatomy, perspective, weight, balance.","Appeal: charisma — heroes and villains both need it.","Even unappealing characters need design clarity.","In 3D, modeling and rigging carry solid drawing's role.","The flour sack exercise tests both without a face."],"qa":[["Flour sack?","The classic test: make a sack feel alive through pose alone."],["Appeal = cute?","No — compelling. Villains need appeal too."],["In 3D?","Modeling, rigging, and posing carry the draftsmanship."]],"title":"Solid Drawing and Appeal","uses":["Character design.","Animation training.","Evaluating performance."]},{"brief":"Lip sync matches mouth shapes to dialogue phonemes — visemes — timed to the audio track, the backbone of dialogue animation.","examples":["A dialogue shot uses a dozen mouth shapes across the line.","Dope sheets map each frame's mouth to the soundtrack."],"history":["1930s studios developed phoneme charts.","Digital tools auto-generate rough lip sync from audio."],"points":["Visemes are visual mouth shapes for sound groups.","Only key sounds need distinct shapes; the rest blend.","Timing matters more than shape accuracy.","Dope sheets (exposure sheets) plan mouth per frame.","Auto-lip-sync gives a rough pass; artists refine."],"qa":[["Viseme vs phoneme?","Phoneme: sound. Viseme: its mouth shape."],["How many shapes?","About 8-12 cover most dialogue."],["Secret to good lip sync?","Timing and jaw motion over perfect shapes."]],"title":"Lip Sync and Dialogue Animation","uses":["Dialogue scenes.","Dubbing and localization.","Game cinematics."]},{"brief":"Character acting makes animated figures think and feel — motivation, subtext, and emotion conveyed through pose, timing, and expression.","examples":["A character's hesitation shows in a half-step and averted eyes.","Pixar acting shines in silent storytelling moments."],"history":["Disney's 1930s animators studied stage acting.","The Illusion of Life (1981) framed animation as acting."],"points":["Every move needs motivation — what is the character thinking?","Eyes lead: the audience reads intention in the gaze.","Contrast stillness with bursts of action.","Subtext: show what the character hides.","Reference yourself: film your own performance."],"qa":[["Animation vs acting?","Animation IS acting — with a pencil or rig instead of a body."],["Key to believable acting?","Thinking: the audience must see thought before motion."],["Reference footage?","Standard practice: act it out, then animate."]],"title":"Character Acting","uses":["Feature and series performance.","Game cinematics.","Acting training for animators."]},{"brief":"The walk cycle — animation's rite of passage — loops contact, down, passing, and up poses to move a character convincingly across the ground.","examples":["A confident stride vs a weary shuffle: same cycle, different timing.","Game locomotion blends walk cycles by speed."],"history":["Muybridge's locomotion studies informed early cycles.","Disney's 1930s animators standardized the four-pose cycle."],"points":["Key poses: contact, down, passing, up — then mirror.","Arms swing opposite the legs.","The head bobs twice per cycle.","Weight shifts side to side.","Personality lives in timing, lean, and arm swing."],"qa":[["Four poses?","Contact, down, passing, up — mirrored for the loop."],["Why do arms swing?","Counter-rotation balances the body — and reads naturally."],["Walk vs run?","Runs add a flight phase with both feet off the ground."]],"title":"Walk Cycles","uses":["Character locomotion.","Game movement systems.","Animation exercises."]},{"brief":"The run cycle adds a flight phase — both feet airborne — with extreme poses, stretched timing, and forward lean conveying speed.","examples":["A sprint cycle leans hard with long flight phases.","Cartoon runs add motion smears and dust puffs."],"history":["Muybridge's gallop studies revealed the flight phase.","Sports analysis refined athletic cycle reference."],"points":["Flight phase: no ground contact — the run's signature.","Lean forward; arms pump hard.","Contact pose lands under the body.","Fewer frames per cycle = faster run.","Smears and multiples sell cartoon speed."],"qa":[["Run vs walk?","Runs have an airborne flight phase; walks always keep a foot down."],["How to show speed?","Longer flight, harder lean, fewer frames."],["Smears?","Stretched in-betweens implying motion blur."]],"title":"Run Cycles","uses":["Action sequences.","Sports games.","Cartoon chases."]},{"brief":"Storyboarding sketches each shot's composition and action; animatics time those boards to audio, creating the film's first editable cut.","examples":["Pixar iterates story reels for months before animating.","A 90-second animatic can save weeks of wasted animation."],"history":["Webb Smith invented storyboarding at Disney in the early 1930s.","Digital tools made animatics standard by the 2000s."],"points":["Boards show framing, action, and dialogue per shot.","Thumbnails first: tiny, fast, disposable.","Animatics add timing, temp audio, and camera moves.","Story reels are screened and revised like live edits.","Bad stories are fixed in boards — never in final animation."],"qa":[["Who invented storyboards?","Webb Smith at Disney, early 1930s."],["Animatic vs storyboard?","Animatic: boards cut to time with audio — a rough movie."],["Why so much iteration?","Fixing story in boards costs little; in animation it costs everything."]],"title":"Storyboarding and Animatics","uses":["Feature and series pre-production.","Commercial planning.","Game cinematic planning."]}];
function buildContent(t,angle){
  var title=t.title,brief=t.brief,pts=t.points,exs=t.examples,his=t.history,uses=t.uses,qa=t.qa;
  var summary,sections,key_facts,i,rest;
  if(angle==='overview'){
    summary=brief+' This overview covers the essentials of '+title+': what it is, why it matters, and where it is used.';
    sections=[{heading:'What it is',body:brief+' '+pts.slice(0,2).join(' ')},{heading:'Key points',body:pts.join(' ')},{heading:'Why it matters',body:uses.slice(0,2).join(' ')}];
    key_facts=pts;
  }else if(angle==='detailed'){
    rest=pts.slice(2);
    summary='A detailed examination of '+title+'. '+brief;
    sections=[{heading:'Core details',body:pts.slice(0,3).join(' ')},{heading:'Going deeper',body:rest.length?rest.join(' '):pts.join(' ')},{heading:'Background and context',body:his.slice(0,2).join(' ')},{heading:'Where it is used',body:uses.join(' ')}];
    key_facts=pts;
  }else if(angle==='examples'){
    summary='Illustrative examples of '+title+' in practice. '+brief;
    sections=[];for(i=0;i<exs.length;i++)sections.push({heading:'Example '+(i+1),body:exs[i]});
    key_facts=pts.slice(0,3);
  }else if(angle==='faq'){
    summary='Frequently asked questions about '+title+'. '+brief;
    sections=[];for(i=0;i<qa.length;i++)sections.push({heading:'Q: '+qa[i][0],body:'A: '+qa[i][1]});
    key_facts=pts.slice(0,3);
  }else if(angle==='history'){
    summary='The background and development of '+title+'. '+brief;
    sections=[];for(i=0;i<his.length;i++)sections.push({heading:'Milestone '+(i+1),body:his[i]});
    key_facts=pts.slice(0,3);
  }else{
    summary='Practical applications of '+title+'. '+brief;
    sections=[];for(i=0;i<uses.length;i++)sections.push({heading:'Application '+(i+1),body:uses[i]});
    key_facts=pts.slice(0,3);
  }
  return{summary:summary,sections:sections,key_facts:key_facts};
}
function defaultDemo(){
  return{kind:'record-program',
    program:"// record card — run with: node demo.js\n// (place the record JSON next to this file as record.json)\nconst card = JSON.parse(require('fs').readFileSync('record.json', 'utf8'));\nconsole.log(card.id + ' — ' + card.title + ' [' + card.src + ']');",
    note:'A runnable program card for this record. Save as demo.js, save the record JSON as record.json beside it, and run with node.'};
}
function generate(seed,opts){
  opts=opts||{};
  var s=(seed>>>0)||1;
  var ti=(((s-1)/6)|0)%TOPICS.length, ai=(s-1)%6;
  var angle=ANGLES[ai];
  if(opts.genre&&ANGLES.indexOf(opts.genre)>=0)angle=opts.genre;
  var t=TOPICS[ti],title=t.title,brief=t.brief,topic=t;
  var ctopic=opts.topic?String(opts.topic).trim().slice(0,120):'';
  if(ctopic){title=ctopic;brief='A user-requested '+RECORD_KIND+' on "'+ctopic+'".';
    topic={title:title,brief:brief,points:t.points,examples:t.examples,history:t.history,uses:t.uses,qa:t.qa,demo:t.demo};}
  var id=PREFIX+pad(s);
  var content=buildContent(topic,angle);
  var demo=topic.demo||defaultDemo();
  return{id:id,title:title+' ('+angle+')',description:brief,genre:angle,type:RECORD_KIND,content:content, content_completeness:'stub',
    stub_note:'Topic stub: the topic title and its one-line brief are real; the full guide article is not yet written. This record does not present shell text as a complete guide.',demo:demo,src:SRC,_seed:s};
}
function validate(r){
  var e=[];
  if(!r||typeof r!=='object')return{ok:false,errors:['not an object']};
  if(typeof r.id!=='string'||r.id.indexOf(PREFIX)!==0||!/\d{6}$/.test(r.id))e.push('id');
  if(typeof r.title!=='string'||r.title.length<8)e.push('title');
  if(typeof r.description!=='string'||r.description.length<40)e.push('description');
  if(ANGLES.indexOf(r.genre)<0)e.push('genre');
  if(!r.content||typeof r.content!=='object'||typeof r.content.summary!=='string'||r.content.summary.length<40)e.push('content');
  if(!r.demo||typeof r.demo!=='object')e.push('demo');
  return{ok:!e.length,errors:e};
}
function driftCheck(rec,sample){
  for(var i=0;i<sample.length;i++){if(sample[i]&&sample[i].t===rec.title)return{ok:false,errors:['duplicate title in archive sample']};}
  return{ok:true,errors:[]};
}
var gen={version:'jahdb-animations-generator-1.0',generate:generate,validate:validate,driftCheck:driftCheck,genres:ANGLES};
if(typeof JAHDB!=='undefined'&&JAHDB.registerGenerator)JAHDB.registerGenerator('animations',gen);
if(typeof module!=='undefined'&&module.exports)module.exports=gen;
})();